SELECT 1;
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE [mabl_TeamSeason] (
  [teamid] int NOT NULL
, [season] int NOT NULL
, [division] nchar(8) NULL COLLATE NOCASE
, [teamname] nchar(50) NULL COLLATE NOCASE
, [clinch_division] bit DEFAULT (0) NOT NULL
, [clinch_playoffs] bit DEFAULT (0) NOT NULL
, [eliminated] bit DEFAULT (0) NOT NULL
, CONSTRAINT [mabl_TeamSeason_PrimaryKey] PRIMARY KEY ([teamid],[season])
);
CREATE TABLE [mabl_TeamCoach] (
  [teamid] int NOT NULL
, [name] nchar(50) NOT NULL COLLATE NOCASE
, [head] bit NOT NULL
, [coachid] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL
, [manager] bit DEFAULT (0) NOT NULL
);
CREATE TABLE [mabl_Team] (
  [teamid] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL
, [name] nchar(50) NOT NULL COLLATE NOCASE
, [abbr] nchar(3) NULL COLLATE NOCASE
);
CREATE TABLE [mabl_SchedulerTeamRestrictions] (
  [id] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL
, [teamid] int NOT NULL
, [season] int NOT NULL
, [start_time] datetime NOT NULL
, [end_time] datetime NOT NULL
);
CREATE TABLE [mabl_SchedulerLocationRestrictions] (
  [id] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL
, [locationid] int NOT NULL
, [season] int NOT NULL
, [start_date] datetime NOT NULL
, [end_date] datetime NOT NULL
);
CREATE TABLE [mabl_SchedulerLocationDays] (
  [id] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL
, [locationid] int NOT NULL
, [season] int NOT NULL
, [dayofweek] nchar(10) NOT NULL COLLATE NOCASE
, [season_start] datetime NOT NULL
, [season_end] datetime NOT NULL
);
CREATE TABLE [mabl_SchedulerDateRestrictions] (
  [id] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL
, [season] int NOT NULL
, [start_time] datetime NOT NULL
, [end_time] datetime NOT NULL
);
CREATE TABLE [mabl_Schedule_Playoffs] (
  [gameid] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL
, [date] datetime NOT NULL
, [locationid] int NOT NULL
, [home_team] int NOT NULL
, [away_team] int NOT NULL
, [home_score] int NULL
, [away_score] int NULL
, [home_errors] int NULL
, [away_errors] int NULL
, [winning_team] int NULL
, [season] int DEFAULT (2010) NOT NULL
, [ppt] bit DEFAULT (0) NOT NULL
, [cancelled] bit DEFAULT (0) NULL
);
CREATE TABLE [mabl_Schedule] (
  [gameid] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL
, [date] datetime NOT NULL
, [locationid] int NOT NULL
, [home_team] int NOT NULL
, [away_team] int NOT NULL
, [home_score] int NULL
, [away_score] int NULL
, [home_errors] int NULL
, [away_errors] int NULL
, [winning_team] int NULL
, [season] int DEFAULT (2007) NOT NULL
, [ppt] bit DEFAULT (0) NOT NULL
, [cancelled] bit DEFAULT (0) NULL
);
CREATE TABLE [mabl_Position] (
  [id] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL
, [abbr] nchar(2) NOT NULL COLLATE NOCASE
, [position] nchar(17) NOT NULL COLLATE NOCASE
);
CREATE TABLE [mabl_PlayerTeam] (
  [playerid] int NOT NULL
, [teamid] int NOT NULL
, [season] int NOT NULL
, [deleted] bit NULL
, CONSTRAINT [mabl_PlayerTeam_PrimaryKey] PRIMARY KEY ([playerid],[teamid],[season])
);
CREATE TABLE [mabl_Player] (
  [id] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL
, [firstname] nchar(40) NOT NULL COLLATE NOCASE
, [lastname] nchar(40) NOT NULL COLLATE NOCASE
, [position] nchar(10) NULL COLLATE NOCASE
, [throws] nchar(1) NULL COLLATE NOCASE
, [bats] nchar(1) NULL COLLATE NOCASE
, [number] int NULL
, [manager] bit NOT NULL
, [dob] datetime DEFAULT (1/1/1960) NULL
, [hometown] nchar(40) NULL COLLATE NOCASE
, [pic] nchar(15) NULL COLLATE NOCASE
);
CREATE TABLE [mabl_Pic] (
  [picid] nchar(10) NOT NULL
, [albumid] int NOT NULL
, [tall] bit NOT NULL
, CONSTRAINT [mabl_Pic_PrimaryKey] PRIMARY KEY ([picid])
);
CREATE TABLE [mabl_News] (
  [id] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL
, [date] datetime NOT NULL
, [title] nchar(80) NOT NULL COLLATE NOCASE
, [news] ntext NOT NULL
, [deleted] bit NOT NULL
, [teamid] int DEFAULT (0) NOT NULL
);
CREATE TABLE [mabl_Location] (
  [id] INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL
, [name] nchar(40) NOT NULL COLLATE NOCASE
, [map] ntext NULL
);
CREATE TABLE [mabl_Innings_Playoffs] (
  [gameid] int NOT NULL
, [inning] int NOT NULL
, [home_score] int NULL
, [away_score] int NULL
, CONSTRAINT [mabl_Innings_PrimaryKey_Playoffs] PRIMARY KEY ([gameid],[inning])
);
CREATE TABLE [mabl_Innings] (
  [gameid] int NOT NULL
, [inning] int NOT NULL
, [home_score] int NULL
, [away_score] int NULL
, CONSTRAINT [mabl_Innings_PrimaryKey] PRIMARY KEY ([gameid],[inning])
);
