CREATE TRIGGER [fki_mabl_GameStatsBatting_Playoffs_teamid_mabl_Team_teamid] BEFORE Insert ON [mabl_GameStatsBatting_Playoffs] FOR EACH ROW BEGIN SELECT RAISE(ROLLBACK, 'Insert on table mabl_GameStatsBatting_Playoffs violates foreign key constraint FK_GameStatsBatting_Playoffs_Team') WHERE NOT EXISTS (SELECT * FROM mabl_Team WHERE  teamid = NEW.teamid); END;
CREATE TRIGGER [fku_mabl_GameStatsBatting_Playoffs_teamid_mabl_Team_teamid] BEFORE Update ON [mabl_GameStatsBatting_Playoffs] FOR EACH ROW BEGIN SELECT RAISE(ROLLBACK, 'Update on table mabl_GameStatsBatting_Playoffs violates foreign key constraint FK_GameStatsBatting_Playoffs_Team') WHERE NOT EXISTS (SELECT * FROM mabl_Team WHERE  teamid = NEW.teamid); END;
CREATE TRIGGER [fki_mabl_GameStatsBatting_teamid_mabl_Team_teamid] BEFORE Insert ON [mabl_GameStatsBatting] FOR EACH ROW BEGIN SELECT RAISE(ROLLBACK, 'Insert on table mabl_GameStatsBatting violates foreign key constraint FK_GameStatsBatting_Team') WHERE NOT EXISTS (SELECT * FROM mabl_Team WHERE  teamid = NEW.teamid); END;
CREATE TRIGGER [fku_mabl_GameStatsBatting_teamid_mabl_Team_teamid] BEFORE Update ON [mabl_GameStatsBatting] FOR EACH ROW BEGIN SELECT RAISE(ROLLBACK, 'Update on table mabl_GameStatsBatting violates foreign key constraint FK_GameStatsBatting_Team') WHERE NOT EXISTS (SELECT * FROM mabl_Team WHERE  teamid = NEW.teamid); END;
COMMIT;

